import json
import boto3
from typing import Dict, Any

def normalize_expense_fields(extracted_text: str) -> Dict[str, Any]:
    """
    Normalizes extracted expense fields into a standard JSON schema using AWS Textract.

    Args:
        extracted_text: Raw text extracted from an expense document (e.g., receipt).

    Returns:
        A dictionary conforming to the standard expense schema:
        {
            "vendor": str,
            "date": str,  # ISO format (YYYY-MM-DD)
            "total": float,
            "items": [
                {
                    "description": str,
                    "quantity": float,
                    "price": float,
                    "amount": float
                }
            ],
            "currency": str  # ISO currency code
        }
    """
    # Initialize AWS Textract client
    textract = boto3.client('textract', region_name='us-east-1')

    # Prepare the document for Textract (assuming extracted_text is from an image/PDF)
    # In practice, you would upload the document to S3 and use its URI here
    # For this example, we simulate the Textract response structure
    response = textract.analyze_expense(
        Document={
            'Bytes': extracted_text.encode() if isinstance(extracted_text, str) else extracted_text
        }
    )

    # Normalize the Textract response into the standard schema
    normalized = {
        "vendor": "",
        "date": "",
        "total": 0.0,
        "items": [],
        "currency": "USD"  # Default, will override if detected
    }

    # Extract vendor, date, total, and currency from summary fields
    for field in response.get('ExpenseDocuments', [{}])[0].get('SummaryFields', []):
        label = field.get('LabelDetection', {}).get('Text', '').lower()
        value = field.get('ValueDetection', {}).get('Text', '')

        if label == 'vendor':
            normalized["vendor"] = value
        elif label == 'date':
            normalized["date"] = value  # Textract returns date in MM/DD/YYYY; normalize to ISO
        elif label == 'total':
            normalized["total"] = float(value.replace(',', ''))
        elif label == 'currency':
            normalized["currency"] = value

    # Extract line items
    for line_item in response.get('ExpenseDocuments', [{}])[0].get('LineItemGroups', [{}])[0].get('LineItems', []):
        item = {
            "description": "",
            "quantity": 1.0,
            "price": 0.0,
            "amount": 0.0
        }
        for field in line_item.get('LineItemExpenseFields', []):
            label = field.get('LabelDetection', {}).get('Text', '').lower()
            value = field.get('ValueDetection', {}).get('Text', '')

            if label == 'description':
                item["description"] = value
            elif label == 'quantity':
                item["quantity"] = float(value)
            elif label == 'price':
                item["price"] = float(value.replace(',', ''))
            elif label == 'amount':
                item["amount"] = float(value.replace(',', ''))

        normalized["items"].append(item)

    # Normalize date to ISO format (YYYY-MM-DD)
    if normalized["date"]:
        try:
            from datetime import datetime
            date_obj = datetime.strptime(normalized["date"], '%m/%d/%Y')
            normalized["date"] = date_obj.strftime('%Y-%m-%d')
        except ValueError:
            pass  # Leave as-is if parsing fails

    return normalized
